import{_ as t,o as s,c as i,a2 as n}from"./chunks/framework.CqpfiAoK.js";const m=JSON.parse('{"title":"Foire Aux Questions (FAQ)","description":"","frontmatter":{},"headers":[],"relativePath":"fr/0096-常见问题FAQ.md","filePath":"fr/0096-常见问题FAQ.md"}'),a={name:"fr/0096-常见问题FAQ.md"};function r(o,e,l,u,d,c){return s(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="foire-aux-questions-faq" tabindex="-1">Foire Aux Questions (FAQ) <a class="header-anchor" href="#foire-aux-questions-faq" aria-label="Permalink to &quot;Foire Aux Questions (FAQ)&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Élément</th><th>Contenu</th></tr></thead><tbody><tr><td>N° de document</td><td>96</td></tr><tr><td>Module</td><td>Annexes et matériaux de référence</td></tr><tr><td>Mots-clés principaux</td><td>questions fréquentes, FAQ, réponses aux questions, clarifications de paramètres, guide d&#39;initiation</td></tr></tbody></table><h2 id="i-notes" tabindex="-1">I. Notes <a class="header-anchor" href="#i-notes" aria-label="Permalink to &quot;I. Notes&quot;">​</a></h2><p>Ce document rassemble les questions fréquentes et leurs réponses concernant le système de paramètres de la Civilisation Symbiotique de l&#39;Ancre, classées par thème. Les questions couvrent tous les aspects : concepts fondamentaux de la vision du monde, système de culture, système social, système juridique, interaction transplanaire, règles temporelles, etc. L&#39;objectif de ce document est de fournir aux lecteurs découvrant pour la première fois le cadre de la Civilisation Symbiotique de l&#39;Ancre un guide d&#39;initiation rapide, tout en offrant aux chercheurs approfondis des réponses faisant autorité aux questions courantes. Ce document est mis à jour en continu ; de nouvelles questions-réponses seront ajoutées en permanence en fonction des retours des lecteurs.</p><h2 id="ii-vision-du-monde-et-concepts-fondamentaux" tabindex="-1">II. Vision du monde et concepts fondamentaux <a class="header-anchor" href="#ii-vision-du-monde-et-concepts-fondamentaux" aria-label="Permalink to &quot;II. Vision du monde et concepts fondamentaux&quot;">​</a></h2><p><strong>Q1 : Quelle est la proposition centrale de la Civilisation Symbiotique de l&#39;Ancre ?</strong> R : La proposition centrale de la Civilisation Symbiotique de l&#39;Ancre est « contre la prédation, pour la symbiose ». Concrètement, elle s&#39;oppose aux systèmes de culture prédatrices qui se font au prix de la dévoration de l&#39;énergie, de la fortune ou même de l&#39;origine des faibles, et prône l&#39;évolution commune par la coopération symbiotique. Le concept fondamental de la civilisation est de « rendre aux êtres vivants le droit de choisir leur destin et leur évolution », et ses lignes directrices de base sont « plus de travail, plus de gain ; croissance autonome ; un chemin pour chacun ; progrès commun des Dix Mille Races ».</p><p><strong>Q2 : Que signifie le principe de « La réalité comme fondement » ?</strong> R : « La réalité comme fondement » est l&#39;une des positions fondamentales de la Civilisation Symbiotique de l&#39;Ancre, signifiant que le monde réel est le seul monde réel et que le monde romanesque est une expérience de pensée fictive. Dans la construction des paramètres, ce qui manque à la fiction est complété par la réalité, et ce qui n&#39;existe pas dans la réalité est créé par amélioration sur la base des lois objectives. Ce principe garantit la cohérence logique et la perceptibilité réelle du système de paramètres, évitant l&#39;effondrement des paramètres causé par une pure spéculation.</p><p><strong>Q3 : Quelle est la relation entre l&#39;Univers Hengyuan et l&#39;univers ?</strong> R : Le nom complet de l&#39;Univers Hengyuan est « Univers Originel Wanling Hengmao ». C&#39;est la totalité de l&#39;univers habité et gouverné par la Civilisation Symbiotique de l&#39;Ancre. Ce n&#39;est pas un univers physique unique au sens ordinaire, mais un être composite formé de quatre niveaux — les plans matériels, les couches d&#39;énergie, le domaine de la conscience et le réseau de lois. On peut comprendre que l&#39;Univers Hengyuan est un super-système universel contenant d&#39;innombrables plans, avec le mécanisme de l&#39;Ancre comme moyen de régulation central.</p><h2 id="iii-systeme-de-culture" tabindex="-1">III. Système de culture <a class="header-anchor" href="#iii-systeme-de-culture" aria-label="Permalink to &quot;III. Système de culture&quot;">​</a></h2><p><strong>Q4 : D&#39;où viennent les Trois Cents Systèmes de Culture d&#39;Origine ?</strong> R : Les Trois Cents Systèmes ne sont pas des techniques fabriquées de toutes pièces, mais des voies de culture orthodoxes directement extraites des lois originelles de l&#39;univers et vérifiées par les Ancres. Pendant la Période d&#39;établissement du système symbiotique, l&#39;équipe dirigée par « Sānbǎi Shī » a procédé à un dégagement et à un classement systématiques des lois de l&#39;univers, aboutissant finalement à la synthèse de Trois Cents systèmes de culture couvrant toutes les dimensions de l&#39;évolution. Ces systèmes se répartissent en six grandes catégories — déduction d&#39;origine, cycle de vie, principes juridiques spatiaux, élévation de la conscience, réseau symbiotique et ingénierie appliquée — avec cinquante systèmes par catégorie.</p><p><strong>Q5 : Pourquoi les trois premiers systèmes sont-ils appelés les « Trois Fondations d&#39;Origine » ?</strong> R : Les trois premiers systèmes — Itération Déductive (système n° 1), Cycle de Vie (système n° 2) et Régulation des Principes Juridiques Spatiaux (système n° 3) — sont les fondations de culture de tous les autres systèmes. Le Système d&#39;Itération Déductive fournit la base de la sagesse et de la méthodologie ; le Système de Cycle de Vie fournit la base de l&#39;énergie vitale ; le Système de Régulation des Principes Juridiques Spatiaux fournit la base des opérations spatiales et juridiques. Il est recommandé aux cultivateurs de tout autre système de pratiquer d&#39;abord au moins une des Trois Fondations d&#39;Origine afin d&#39;établir une base d&#39;évolution stable.</p><p><strong>Q6 : Qu&#39;est-ce que le Fruit Multiplicateur ? Quel est son rapport avec One Piece ?</strong> R : Le Fruit Multiplicateur est l&#39;un des « buffs de départ » de la Civilisation Symbiotique de l&#39;Ancre, issu du paramètre du Fruit Multiplicateur du monde de One Piece. Dans l&#39;Univers Hengyuan, le Fruit Multiplicateur a fait l&#39;objet d&#39;une application technologique : il peut décupler cent fois la capacité déductive du cultivateur, et constitue l&#39;outil auxiliaire central du Système d&#39;Itération Déductive. Ce paramètre illustre le principe de « compléter ce qui manque à la fiction par la réalité, et créer par amélioration sur la base des lois ce que la réalité ne possède pas » — les paramètres intéressants des œuvres de fiction sont intégrés au système technologique de la civilisation symbiotique après une adaptation fondée sur les lois.</p><p><strong>Q7 : Qu&#39;est-ce que la Stratégie d&#39;activation de 20 % ? Pourquoi 20 % ?</strong> R : La Stratégie d&#39;activation de 20 % est un objectif stratégique par étapes de la Civilisation Symbiotique de l&#39;Ancre, visant à activer dès la première phase 20 % de tous les êtres vivants de l&#39;univers en Puissances Suprêmes du Plan. Le choix du taux de 20 % repose sur l&#39;analyse dynamique du réseau symbiotique — lorsqu&#39;un réseau compte 20 % de ses nœuds à l&#39;état de haute énergie, l&#39;effet de résonance global du réseau déclenche un point critique, entraînant l&#39;accélération de l&#39;évolution des 80 % de nœuds restants. Ces 20 % de Puissances Suprêmes du Plan serviront de force d&#39;ossature et joueront un rôle central dans l&#39;entretien des Ancres, l&#39;orientation des mentors et la construction de la civilisation.</p><h2 id="iv-systeme-social-et-droit" tabindex="-1">IV. Système social et droit <a class="header-anchor" href="#iv-systeme-social-et-droit" aria-label="Permalink to &quot;IV. Système social et droit&quot;">​</a></h2><p><strong>Q8 : Que sont les Cinq Typologies de Civilisations Symbiotiques ?</strong> R : Les Cinq Typologies de Civilisations Symbiotiques sont cinq types de sociétés symbiotiques définis sur la base des caractéristiques des civilisations du monde réel : le type intensif d&#39;Asie de l&#39;Est (caractérisé par une organisation très efficace et le collectivisme), le type de bien-être nordique (caractérisé par une haute protection sociale et l&#39;égalité sociale), le type pluraliste d&#39;Amérique du Nord (caractérisé par des cultures diverses et une vitalité innovante), le type social continental européen (caractérisé par l&#39;économie sociale de marché et la participation des travailleurs) et le type de rattrapage en développement (caractérisé par un développement rapide et les avantages du retardataire). Ces cinq typologies ne sont pas des classifications exclusives, mais des modèles de référence pouvant s&#39;inspirer mutuellement et se développer par fusion.</p><p><strong>Q9 : Comment fonctionne le Mécanisme de contrat lié à la production ?</strong> R : Le Mécanisme de contrat lié à la production est le système central de répartition des ressources de la Civilisation Symbiotique de l&#39;Ancre, inspiré du système réel de responsabilité contractuelle liée à la production au niveau des ménages. Son mode de fonctionnement est le suivant : les ressources de culture de l&#39;univers sont réparties entre les individus ou les groupes sous forme de « contrat » ; les contractants obtiennent le droit d&#39;usage et le droit aux bénéfices des ressources par le travail et les contributions. Plus de travail, plus de gain — plus la contribution est grande, plus les ressources obtenues sont importantes. Ce mécanisme garantit à la fois la répartition équitable des ressources et stimule l&#39;initiative au travail des individus, réalisant l&#39;unité de l&#39;équité et de l&#39;efficacité.</p><p><strong>Q10 : Quelle est la relation entre la Constitution Symbiotique et les lois ordinaires ?</strong> R : La Constitution Symbiotique est la loi fondamentale de la Civilisation Symbiotique de l&#39;Ancre et possède la plus haute force juridique. Toutes les lois, règlements administratifs et règlements locaux ne doivent pas être en contradiction avec la Constitution. La Loi Symbiotique du Travail, la Loi sur la protection des consommateurs et les cinq lois d&#39;accompagnement sur l&#39;éducation, la santé, le logement, l&#39;environnement et l&#39;antitrust sont toutes des lois sectorielles établies sur la base législative de la Constitution Symbiotique, chargées de concrétiser et de rendre opérationnelles les dispositions de principe de la Constitution. Le Tribunal Symbiotique a le pouvoir de procéder au contrôle de constitutionnalité des lois contraires à la Constitution et de les déclarer nulles.</p><h2 id="v-interaction-transplanaire" tabindex="-1">V. Interaction transplanaire <a class="header-anchor" href="#v-interaction-transplanaire" aria-label="Permalink to &quot;V. Interaction transplanaire&quot;">​</a></h2><p><strong>Q11 : Qu&#39;est-ce que le schéma archéologique « Miroir de Réplication + espace isolé + restitution de connaissances uniquement » ?</strong> R : C&#39;est le schéma standard de l&#39;archéologie transplanaire et de la régression temporelle de la Civilisation Symbiotique de l&#39;Ancre, composé de trois éléments essentiels :</p><ol><li><strong>Miroir de Réplication</strong> : effectue une réplication complète 1:1 de la cible archéologique sans toucher à l&#39;original ; le processus de réplication ne modifie aucun état de l&#39;original.</li><li><strong>Espace isolé</strong> : la copie est générée dans un espace indépendant totalement isolé de la cible ; les archéologues effectuent toutes les opérations de recherche dans l&#39;espace isolé.</li><li><strong>Restitution de connaissances uniquement</strong> : à la fin de l&#39;archéologie, seules des connaissances et des informations abstraites peuvent être restituées ; la matière et l&#39;énergie de la copie doivent être détruites dans l&#39;espace isolé et ne doivent pas être ramenées dans le plan d&#39;origine. Ce schéma garantit une interférence nulle du processus archéologique avec le plan cible ou la période cible, tout en prévenant la pollution transplanaire.</li></ol><p><strong>Q12 : Pourquoi faut-il respecter le principe d&#39;« observer d&#39;abord, puis intervenir dans les limites » ?</strong> R : Le concept central de ce principe est l&#39;« humilité cognitive » — même une Puissance Suprême du Plan ne peut saisir pleinement toutes les relations causales d&#39;un nœud temporel ou d&#39;une civilisation de plan. Toute intervention directe dans le passé ou dans un autre plan peut déclencher des réactions en chaîne causales imprévisibles. Par conséquent, une observation globale doit d&#39;abord être menée avec l&#39;attitude la plus prudente, et ce n&#39;est que lorsque les données d&#39;observation sont suffisantes et l&#39;évaluation des risques claire qu&#39;une intervention limitée, strictement bornée en portée et en degré, est autorisée. Ce principe est la garantie fondamentale de la sécurité de la régression temporelle et des opérations transplanaires.</p><p><strong>Q13 : Quelles conditions sont requises pour la traversée transplanaire ?</strong> R : La traversée de plan exige les conditions suivantes : premièrement, le voyageur doit posséder une culture au troisième rang du Système de Régulation des Principes Juridiques Spatiaux (le Stade Huàkōng) ou supérieur, ou être transporté par un véhicule de traversée conforme aux normes ; deuxièmement, un permis de traversée du niveau correspondant délivré par l&#39;Administration des Plans doit être obtenu (niveau A : observation archéologique, niveau B : échange académique, niveau C : coopération de ressources, niveau D : intervention d&#39;urgence) ; troisièmement, le point de départ et le point d&#39;arrivée doivent tous deux posséder des Ancres pour l&#39;étalonnage des coordonnées ; quatrièmement, les trois procédures de purification (purification biologique, purification énergétique, purification de la conscience) doivent être accomplies ; cinquièmement, l&#39;énergie de traversée doit être portée par le voyageur lui-même, et il est interdit d&#39;en extraire du plan cible.</p><h2 id="vi-regles-temporelles" tabindex="-1">VI. Règles temporelles <a class="header-anchor" href="#vi-regles-temporelles" aria-label="Permalink to &quot;VI. Règles temporelles&quot;">​</a></h2><p><strong>Q14 : Quelle est la différence entre la régression temporelle et le voyage dans le temps ?</strong> R : Dans le cadre de l&#39;Univers Hengyuan, la régression temporelle n&#39;équivaut pas au voyage dans le temps. Le régressif temporel n&#39;entre pas dans le passé sous une forme matérielle complète, mais atteint le nœud temporel cible sous la forme d&#39;une projection de conscience ou d&#39;un paquet d&#39;informations. L&#39;existence du régressif dans la période passée est « semi-transparente » — observable, mais avec une capacité d&#39;interaction physique strictement limitée. Cette conception fait elle-même partie du mécanisme de sécurité de la régression temporelle, réduisant la possibilité pour le régressif de causer une interférence physique sur le passé.</p><p><strong>Q15 : Quels sont les types de paradoxes temporels ? Comment les prévenir et les contrôler ?</strong> R : Les paradoxes temporels se divisent en quatre grandes catégories : le paradoxe du parricide (les actions du régressif éliminent les conditions causales de sa propre existence), le paradoxe informationnel (les informations transmises du futur au passé forment une boucle informationnelle sans source), le paradoxe ontologique (l&#39;interaction du régressif avec son soi passé provoque une confusion de la conscience ontologique) et le paradoxe événementiel (le régressif modifie des événements historiques clés, entraînant la reconstruction de la chaîne causale). Les mécanismes de prévention et de contrôle comprennent : l&#39;évaluation causale préalable à la régression et l&#39;isolation causale du régressif avant l&#39;opération, le système de liste blanche des comportements d&#39;intervention pendant l&#39;opération, la surveillance causale en temps réel et la réponse d&#39;urgence à trois niveaux pendant l&#39;opération, et la réparation causale et l&#39;audit après l&#39;opération. L&#39;objectif de tout le système de prévention et de contrôle est d&#39;éliminer les paradoxes dès leur naissance.</p><h2 id="vii-vie-et-races" tabindex="-1">VII. Vie et races <a class="header-anchor" href="#vii-vie-et-races" aria-label="Permalink to &quot;VII. Vie et races&quot;">​</a></h2><p><strong>Q16 : Que sont la Vie Anomale et l&#39;Énergie Anomale ?</strong> R : La Vie Anomale désigne les formes de vie qui ne correspondent pas à la définition conventionnelle de la vie et possèdent des formes d&#39;existence spéciales, comme la vie à énergie pure, la vie sous forme de conscience et la vie mécanique. L&#39;Énergie Anomale désigne les formes d&#39;énergie qui ne correspondent pas à la classification conventionnelle de l&#39;énergie et possèdent des attributs et des comportements spéciaux, comme l&#39;énergie de loi, l&#39;énergie de conscience et l&#39;énergie causale. Pour ces deux types d&#39;existences spéciales, la Civilisation Symbiotique de l&#39;Ancre a établi trois types de procédures de traitement normalisées (identification et classification, évaluation et contrôle, intégration et symbiose), garantissant qu&#39;elles sont correctement gérées et rationnellement utilisées dans le cadre de la civilisation symbiotique.</p><p><strong>Q17 : Qu&#39;est-ce qu&#39;une Entité Sombre de Remplacement ? En quoi consistent les Directives Éthiques des Deux Âmes ?</strong> R : Une Entité Sombre de Remplacement est une forme de vie spéciale dont le corps abrite simultanément deux âmes — généralement une âme native et une âme « de remplacement » externe. Cet état soulève des questions éthiques complexes : les deux âmes possèdent chacune leurs droits et leurs personnalités, et l&#39;une ne peut être simplement éliminée. Le cœur des Directives Éthiques des Deux Âmes est de respecter les droits respectifs des deux âmes et d&#39;interdire la fusion forcée ou l&#39;élimination unilatérale. Selon la situation spécifique, les Entités Sombres de Remplacement se répartissent en quatre branches, chacune adoptant un traitement différent : le type de coexistence (les deux âmes coexistent harmonieusement), le type d&#39;alternance (les deux âmes contrôlent le corps à tour de rôle), le type de séparation (les deux âmes sont séparées dans des supports différents par des moyens techniques) et le type de fusion (fusion profonde en une nouvelle âme sur la base du volontariat des deux parties).</p><h2 id="viii-methodologie-des-parametres" tabindex="-1">VIII. Méthodologie des paramètres <a class="header-anchor" href="#viii-methodologie-des-parametres" aria-label="Permalink to &quot;VIII. Méthodologie des paramètres&quot;">​</a></h2><p><strong>Q18 : En quoi ce système de paramètres diffère-t-il des paramètres ordinaires de romans en ligne ?</strong> R : La plus grande différence du système de paramètres de la Civilisation Symbiotique de l&#39;Ancre réside dans sa position centrale « anti-prédation ». Les paramètres ordinaires de romans en ligne placent souvent au centre la croissance personnelle et l&#39;élévation de la puissance du protagoniste, et le système de culture y est essentiellement prédateur — le protagoniste devient plus fort en dévorant, en combattant et en s&#39;emparant des ressources. La Civilisation Symbiotique de l&#39;Ancre s&#39;oppose fondamentalement à ce modèle et prône l&#39;évolution commune des Dix Mille Races par la coopération symbiotique. En outre, ce système de paramètres insiste sur « La réalité comme fondement » : tous les paramètres s&#39;efforcent d&#39;être logiquement cohérents et conformes aux lois objectives, évitant la pure spéculation et l&#39;effondrement des paramètres.</p><p><strong>Q19 : Qu&#39;est-ce que la Voie d&#39;Élévation en Quatre Étapes, concrètement ?</strong> R : La Voie d&#39;Élévation en Quatre Étapes est la route stratégique de l&#39;élévation globale de l&#39;Univers Hengyuan :</p><ol><li><strong>Fondation de la réalité</strong> : établir un système social symbiotique sur les plans matériels, éliminer la racine de la prédation et achever la construction des fondations institutionnelles de la civilisation.</li><li><strong>Autonomisation technologique</strong> : combiner les lois de culture avec l&#39;ingénierie technologique, abaisser le seuil de l&#39;évolution et réaliser un bond des forces productives.</li><li><strong>Évolution de la conscience</strong> : promouvoir la migration des formes de vie vers le domaine de la conscience, réalisant la symbiose et la sublimation au niveau spirituel.</li><li><strong>Symbiose interstellaire</strong> : établir un réseau complet d&#39;Ancres à travers les plans et les étoiles, achevant l&#39;élévation globale de l&#39;univers. L&#39;Univers Hengyuan se trouve actuellement dans la période charnière du passage de la première à la deuxième étape.</li></ol><p><strong>Q20 : Comment participer à l&#39;expansion de ce système de paramètres ?</strong> R : Le système de paramètres de la Civilisation Symbiotique de l&#39;Ancre est un système ouvert, en expansion continue. Toute personne peut créer des extensions sur la base du cadre existant, y compris, sans s&#39;y limiter : détailler les méthodes concrètes d&#39;un système de culture donné, créer la culture et l&#39;histoire d&#39;une race donnée, concevoir la forme de civilisation d&#39;un plan donné, rédiger les événements détaillés d&#39;une période historique donnée, et développer de nouvelles technologies et de nouveaux scénarios d&#39;application. Les paramètres d&#39;extension doivent suivre le principe de « La réalité comme fondement, l&#39;amélioration par les lois », garantissant la cohérence logique avec les paramètres existants. Les excellentes extensions peuvent être intégrées au système officiel après examen.</p><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>La FAQ est le point d&#39;entrée rapide dans le monde des paramètres de la Civilisation Symbiotique de l&#39;Ancre. À travers ces vingt questions-réponses, les lecteurs peuvent saisir rapidement les concepts fondamentaux, les mécanismes clés et le cadre de base du système de paramètres. Bien sûr, la FAQ ne peut couvrir tous les détails du système de paramètres ; la compréhension approfondie exige la lecture des documents spécialisés de chaque module. À mesure que le système de paramètres s&#39;enrichit, cette FAQ sera également mise à jour en continu, servant toujours de référence fiable pour l&#39;initiation et les questions des lecteurs.</p><h2 id="documents-associes" tabindex="-1">Documents associés <a class="header-anchor" href="#documents-associes" aria-label="Permalink to &quot;Documents associés&quot;">​</a></h2><ul><li>00-衡元宙宇宙总览 (Heng Yuan Zhou : Vue d&#39;ensemble du Cosmos)</li><li>90-术语词典 (Le Dictionnaire de Terminologie)</li><li>98-扩展设定建议清单 (Liste de Suggestions de Paramètres Étendus)</li></ul>',37)])])}const v=t(a,[["render",r]]);export{m as __pageData,v as default};
